function ProductManager(){const[list,setList]=useState<Product[]>(products);const[q,setQ]=useState('');const[cat,setCat]=useState('All');const[page,setPage]=useState(1);const[editing,setEditing]=useState<Product|null>(null);const filtered=useMemo(()=>list.filter(p=>(cat==='All'||p.category===cat)&&(p.name+p.brand+p.sku).toLowerCase().includes(q.toLowerCase())),[list,q,cat]);const shown=filtered.slice((page-1)*20,page*20);const save=(p:Product)=>{const next=list.some(x=>x.id===p.id)?list.map(x=>x.id===p.id?p:x):[p,...list];setList(next);persistCatalog(next);setEditing(null)};const remove=(id:number)=>{if(confirm('Remove this product from the local demonstration catalog?')){const next=list.filter(p=>p.id!==id);setList(next);persistCatalog(next)}};const exportCatalog=()=>{const csv=['SKU,NAME,BRAND,CATEGORY,PRICE,STOCK,CASE_PACK',...list.map(p=>[p.sku,p.name,p.brand,p.category,p.price,p.stock,p.casePack].map(v=>`"${String(v).replaceAll('"','""')}"`).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='meridian-product-catalog.csv';a.click();URL.revokeObjectURL(a.href)};const importCatalog=(file?:File)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>{const lines=String(reader.result).split(/\r?\n/).slice(1).filter(Boolean);const additions=lines.map((line,i)=>{const cols=line.match(/("[^"]*(?:""[^"]*)*"|[^,]+)/g)?.map(v=>v.replace(/^"|"$/g,'').replaceAll('""','"'))||[];const p=blankProduct();return{...p,id:Date.now()+i,sku:cols[0]||`IMPORT-${i}`,name:cols[1]||'Imported product',brand:cols[2]||'Imported',category:cols[3]||'General Merchandise',price:+cols[4]||0,stock:+cols[5]||0,casePack:+cols[6]||12,slug:(cols[1]||`imported-${i}`).toLowerCase().replace(/[^a-z0-9]+/g,'-')}});const next=[...additions,...list];setList(next);persistCatalog(next)};reader.readAsText(file)};return <div className="admin-workspace"><div className="admin-toolbar"><div className="admin-search"><Search/><input value={q} onChange={e=>{setQ(e.target.value);setPage(1)}} placeholder="Search product, brand or SKU"/></div><select value={cat} onChange={e=>{setCat(e.target.value);setPage(1)}}><option>All</option>{categories.map(c=><option key={c}>{c}</option>)}</select><button className="admin-primary" onClick={()=>setEditing(blankProduct())}><Plus/>Add product</button></div><div className="admin-result-meta"><span>{filtered.length} products</span><div><label className="admin-import">Import CSV<input type="file" accept=".csv" onChange={e=>importCatalog(e.target.files?.[0])}/></label><button onClick={exportCatalog}>Export catalog</button></div></div><div className="admin-product-table"><div className="apt-head"><span>PRODUCT</span><span>INVENTORY</span><span>WHOLESALE</span><span>STATUS</span><span>FLAGS</span><span></span></div>{shown.map(p=><div className="apt-row" key={p.id}><div><img src={p.image}/><span><b>{p.name}</b><BrandLogo brand={p.brand} variant="micro" showName/><small>{p.sku}</small></span></div><span><b>{p.stock} cases</b><small>Case of {p.casePack}</small></span><span><b>${p.price.toFixed(2)}</b><small>MSRP ${p.msrp.toFixed(2)}</small></span><span className={p.stock?'admin-status green':'admin-status red'}>{p.stock?'Active':'Out of stock'}</span><span><i>{p.tags[0]}</i></span><div><button onClick={()=>setEditing(p)}><Edit3/></button><button onClick={()=>remove(p.id)}><Trash2/></button></div></div>)}</div><div className="admin-pagination"><button disabled={page===1} onClick={()=>setPage(page-1)}>Previous</button><span>Page {page} of {Math.max(1,Math.ceil(filtered.length/20))}</span><button disabled={page>=Math.ceil(filtered.length/20)} onClick={()=>setPage(page+1)}>Next</button></div>{editing&&<ProductEditor product={editing} onClose={()=>setEditing(null)} onSave={save}/>}</div>}
function blankProduct():Product{return{id:Date.now(),slug:'new-product-'+Date.now(),name:'',brand:'',category:'General Merchandise',sku:'',price:0,msrp:0,casePack:12,moq:1,stock:0,tags:['New'],tone:'#f3f4f6',image:'/images/products/lattafa-perfume-khamrah-asad-yara-produc-1.webp',gallery:[],rating:0,reviews:0,orders:0,supplier:'Meridian Supply Co.',verified:false,size:'Single retail pack',origin:'United States inventory',concentration:'Not applicable',audience:'General',fragranceFamily:'Not applicable',leadTime:'2–5 days',shelfLife:'Manufacturer specification',documents:false,sample:false,returnable:false,metricsAreDemo:true}}
function ProductEditor({product,onClose,onSave}:{product:Product;onClose:()=>void;onSave:(p:Product)=>void}){const[p,setP]=useState({...product});const f=(key:keyof Product,value:any)=>setP(x=>({...x,[key]:value}));return <div className="admin-modal"><form onSubmit={e=>{e.preventDefault();onSave({...p,slug:p.slug||p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),gallery:p.gallery.length?p.gallery:[p.image,p.image,p.image,p.image]})}}><header><div><small>CATALOG MANAGEMENT</small><h2>{product.name?'Edit product':'Add product'}</h2></div><button type="button" onClick={onClose}><X/></button></header><div className="admin-form-grid"><label className="full">Product name<input value={p.name} onChange={e=>f('name',e.target.value)} required/></label><label>Brand<input value={p.brand} onChange={e=>f('brand',e.target.value)} required/></label><label>Category<select value={p.category} onChange={e=>f('category',e.target.value)}>{categories.map(c=><option key={c}>{c}</option>)}</select></label><label>SKU<input value={p.sku} onChange={e=>f('sku',e.target.value)} required/></label><label>Size / pack<input value={p.size} onChange={e=>f('size',e.target.value)}/></label><label>Wholesale unit price<input type="number" step=".01" value={p.price} onChange={e=>f('price',+e.target.value)}/></label><label>MSRP<input type="number" step=".01" value={p.msrp} onChange={e=>f('msrp',+e.target.value)}/></label><label>Inventory cases<input type="number" value={p.stock} onChange={e=>f('stock',+e.target.value)}/></label><label>Units per case<input type="number" value={p.casePack} onChange={e=>f('casePack',+e.target.value)}/></label><label>Minimum cases<input type="number" value={p.moq} onChange={e=>f('moq',+e.target.value)}/></label><label>Lead time<input value={p.leadTime} onChange={e=>f('leadTime',e.target.value)}/></label><label className="full">Primary image path<input value={p.image} onChange={e=>f('image',e.target.value)}/></label><label className="full admin-image-upload">Upload product image<input type="file" accept="image/*" onChange={e=>{const file=e.target.files?.[0];if(file){const reader=new FileReader();reader.onload=()=>f('image',String(reader.result));reader.readAsDataURL(file)}}}/>{p.image&&<img src={p.image}/>}</label><label>Badge<select value={p.tags[0]} onChange={e=>f('tags',[e.target.value])}><option>New</option><option>Best Seller</option><option>Deal</option><option>Ready to Ship</option></select></label><label>Supplier<input value={p.supplier} onChange={e=>f('supplier',e.target.value)}/></label><div className="admin-checks full"><label><input type="checkbox" checked={p.verified} onChange={e=>f('verified',e.target.checked)}/>Verified inventory</label><label><input type="checkbox" checked={p.sample} onChange={e=>f('sample',e.target.checked)}/>Samples available</label><label><input type="checkbox" checked={p.documents} onChange={e=>f('documents',e.target.checked)}/>Documents available</label><label><input type="checkbox" checked={p.returnable} onChange={e=>f('returnable',e.target.checked)}/>Return eligible</label></div></div><footer><button type="button" onClick={onClose}>Cancel</button><button className="admin-primary"><Save/>Save product</button></footer></form></div>}
function TaxonomyManager(){return <div className="admin-taxonomy"><Taxonomy title="Brands" items={brands}/><Taxonomy title="Categories" items={categories}/></div>};function Taxonomy({title,items}:{title:string;items:string[]}){const[list,setList]=useState(items);const[value,setValue]=useState('');const commit=(next:string[])=>{setList(next);title==='Brands'?persistBrands(next):persistCategories(next)};return <section><header><div><h2>{title}</h2><span>{list.length} entries</span></div><form onSubmit={e=>{e.preventDefault();if(value.trim()&&!list.includes(value))commit([...list,value.trim()]);setValue('')}}><input value={value} onChange={e=>setValue(e.target.value)} placeholder={`Add ${title.toLowerCase().slice(0,-1)}`}/><button><Plus/></button></form></header>{list.map((x,i)=><div key={x}><span>{String(i+1).padStart(2,'0')}</span>{title==='Brands'?<BrandLogo brand={x} variant="micro" showName/>:<b>{x}</b>}<small>{products.filter(p=>(title==='Brands'?p.brand:p.category)===x).length} products</small><button onClick={()=>{const name=window.prompt(`Rename ${title.toLowerCase().slice(0,-1)}`,x);if(name&&name.trim())commit(list.map(v=>v===x?name.trim():v))}}><Edit3/></button><button onClick={()=>commit(list.filter(v=>v!==x))}><Trash2/></button></div>)}</section>}
