function DataWorkspace({type}:{type:string}){const d=data[type];const[rows,setRows]=useState<string[][]>(()=>loadAdminRows(type,d.rows));const[q,setQ]=useState('');const[editing,setEditing]=useState<{index:number;row:string[]}|null>(null);const[replying,setReplying]=useState<{index:number;row:string[]}|null>(null);const filtered=rows.map((row,index)=>({row,index})).filter(x=>x.row.join(' ').toLowerCase().includes(q.toLowerCase()));const save=(row:string[])=>{const next=editing&&editing.index>=0?rows.map((r,i)=>i===editing.index?row:r):[row,...rows];setRows(next);saveAdminRows(type,next);setEditing(null)};const remove=(index:number)=>{const next=rows.filter((_,i)=>i!==index);setRows(next);saveAdminRows(type,next)};return <div className="admin-workspace"><div className="admin-page-intro"><div><h2>{d.title}</h2><p>{d.intro}</p></div><div><button onClick={()=>{const blob=new Blob([d.headers.join(',')+'\n'+rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=type+'.csv';a.click()}}>Export CSV</button><button className="admin-primary" onClick={()=>setEditing({index:-1,row:d.headers.map(()=> '')})}><Plus/>Add record</button></div></div><div className="admin-search wide"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder={`Search ${type}`}/></div><AdminTable headers={[...d.headers,'Actions']} rows={filtered.map(x=>[...x.row,''])} onEdit={i=>setEditing({index:filtered[i].index,row:[...filtered[i].row]})} onDelete={i=>remove(filtered[i].index)} onReply={['rfqs','inquiries','reviews'].includes(type)?i=>setReplying({index:filtered[i].index,row:[...filtered[i].row]}):undefined}/>{editing&&<RecordEditor title={d.title} headers={d.headers} initial={editing.row} onClose={()=>setEditing(null)} onSave={save}/>} {replying&&<ResponseComposer reference={replying.row[0]} recipient={replying.row[1]} onClose={()=>setReplying(null)} onSend={message=>{const next=rows.map((r,i)=>i===replying.index?r.map((v,n)=>n===r.length-1?'Replied':v):r);setRows(next);saveAdminRows(type,next);localStorage.setItem(`ms-admin-response-${type}-${replying.row[0]}`,message);setReplying(null)}}/>}</div>}
function AdminTable({headers,rows,onEdit,onDelete,onReply}:{headers:string[];rows:string[][];onEdit?:(i:number)=>void;onDelete?:(i:number)=>void;onReply?:(i:number)=>void}){return <div className="admin-data-table"><div style={{gridTemplateColumns:`repeat(${headers.length},minmax(110px,1fr))`}}>{headers.map(h=><b key={h}>{h}</b>)}</div>{rows.map((r,i)=><div style={{gridTemplateColumns:`repeat(${headers.length},minmax(110px,1fr))`}} key={i}>{r.map((x,j)=>j===r.length-1&&onEdit?<span className="admin-row-actions" key={j}>{onReply&&<button title="Reply" onClick={()=>onReply(i)}><Reply/></button>}<button title="Edit" onClick={()=>onEdit(i)}><Edit3/></button><button onClick={()=>onDelete?.(i)}><Trash2/></button></span>:<span className={j===r.length-2?'admin-status':''} key={j}>{x}</span>)}</div>)}</div>}
function RecordEditor({title,headers,initial,onClose,onSave}:{title:string;headers:string[];initial:string[];onClose:()=>void;onSave:(r:string[])=>void}){const[row,setRow]=useState(initial);return <div className="admin-modal"><form onSubmit={e=>{e.preventDefault();onSave(row)}}><header><div><small>OPERATIONS MANAGEMENT</small><h2>{title} record</h2></div><button type="button" onClick={onClose}><X/></button></header><div className="admin-form-grid">{headers.map((h,i)=><label key={h}>{h}<input required value={row[i]||''} onChange={e=>setRow(r=>r.map((v,n)=>n===i?e.target.value:v))}/></label>)}</div><footer><button type="button" onClick={onClose}>Cancel</button><button className="admin-primary"><Save/>Save record</button></footer></form></div>}
function ResponseComposer({reference,recipient,onClose,onSend}:{reference:string;recipient:string;onClose:()=>void;onSend:(m:string)=>void}){const[message,setMessage]=useState(`Hello ${recipient},\n\nThank you for contacting Meridian Supply Co. regarding ${reference}. Our team has reviewed your request and will continue the conversation through the appropriate account workflow.\n\nRegards,\nMeridian Operations`);const templates=[['Acknowledgement',`Thank you for your request regarding ${reference}. It has been assigned to our operations team.`],['More information',`We are reviewing ${reference}. Please provide the related SKU, quantity and delivery ZIP code.`],['Completed',`Your request ${reference} has been reviewed and marked complete. Contact us if additional assistance is needed.`]];return <div className="admin-modal"><form onSubmit={e=>{e.preventDefault();onSend(message)}}><header><div><small>RESPONSE WORKSPACE</small><h2>Reply to {reference}</h2><p>Recipient: {recipient}</p></div><button type="button" onClick={onClose}><X/></button></header><div className="response-composer"><div className="response-templates">{templates.map(([a,b])=><button type="button" key={a} onClick={()=>setMessage(b)}>{a}</button>)}</div><label>Response message<textarea rows={10} required value={message} onChange={e=>setMessage(e.target.value)}/></label><small>Frontend preview: the response is saved locally. Connect an email or messaging service to deliver it externally.</small></div><footer><button type="button" onClick={onClose}>Cancel</button><button className="admin-primary"><Send/>Save response</button></footer></form></div>}
function ContentManager(){const[content,setContent]=useState<SiteContent>(getSiteContent);const[message,setMessage]=useState('');const fields:[keyof SiteContent,string,string][]=[['heroHeading','Homepage hero headline','Primary homepage positioning statement'],['heroBody','Homepage hero description','Supporting wholesale distribution message'],['announcement','Announcement bar','Global storefront notice'],['promoHeading','Promotional campaign headline','Homepage campaign heading'],['promoBody','Promotional campaign description','Campaign supporting content'],['footerDescription','Footer company description','Global distribution summary'],['supportEmail','Support email','Customer service routing address']];const save=()=>{saveSiteContent(content);setMessage('Published storefront content saved locally')};return <div className="content-manager"><div className="admin-page-intro"><div><h2>Website content</h2><p>Manage content that is rendered directly on the public storefront.</p></div><button className="admin-primary" onClick={save}><Save/>Publish changes</button></div>{message&&<div className="admin-notice"><CheckCircle2/>{message}</div>}<div className="content-editor-grid">{fields.map(([key,label,help],i)=><label key={key}><span>{String(i+1).padStart(2,'0')}</span><div><b>{label}</b><small>{help}</small><textarea value={content[key]} onChange={e=>setContent(x=>({...x,[key]:e.target.value}))}/></div></label>)}</div></div>}
function SettingsManager(){const[settings,setSettings]=useState<CommerceSettings>(getCommerceSettings);const[saved,setSaved]=useState(false);const update=<K extends keyof CommerceSettings>(key:K,value:CommerceSettings[K])=>setSettings(x=>({...x,[key]:value}));return <div className="settings-manager"><div className="admin-page-intro"><div><h2>Platform configuration</h2><p>Control commercial rules, account behavior and storefront localization.</p></div><button className="admin-primary" onClick={()=>{saveCommerceSettings(settings);setSaved(true)}}><Save/>Save settings</button></div>{saved&&<div className="admin-notice"><CheckCircle2/>Platform settings saved locally</div>}<div className="settings-form"><label><span>Commerce</span><div><b>Guest pricing visibility</b><small>Control protected wholesale pricing behavior.</small></div><select value={settings.guestPricing} onChange={e=>update('guestPricing',e.target.value as CommerceSettings['guestPricing'])}><option value="hidden">Hidden until approval</option><option value="visible">Visible to guests</option></select></label><label><span>Commerce</span><div><b>Default pricing tier</b><small>New approved-account pricing tier.</small></div><input value={settings.defaultTier} onChange={e=>update('defaultTier',e.target.value)}/></label><label><span>Orders</span><div><b>Default minimum order</b><small>Demonstration merchandise threshold.</small></div><input type="number" value={settings.minimumOrder} onChange={e=>update('minimumOrder',+e.target.value)}/></label><label><span>Inventory</span><div><b>Low-stock threshold</b><small>Cases remaining before an alert appears.</small></div><input type="number" value={settings.lowStockThreshold} onChange={e=>update('lowStockThreshold',+e.target.value)}/></label><label><span>Applications</span><div><b>Approval workflow</b><small>Business-account approval behavior.</small></div><select value={settings.applicationApproval} onChange={e=>update('applicationApproval',e.target.value as CommerceSettings['applicationApproval'])}><option value="manual">Manual verification</option><option value="automatic">Automatic demonstration approval</option></select></label><label><span>Reviews</span><div><b>Verified-purchaser requirement</b><small>Require transaction eligibility for verified badges.</small></div><input type="checkbox" checked={settings.verifiedReviews} onChange={e=>update('verifiedReviews',e.target.checked)}/></label><label><span>Localization</span><div><b>Market</b><small>Primary storefront market.</small></div><input value={settings.market} onChange={e=>update('market',e.target.value)}/></label><label><span>Localization</span><div><b>Currency</b><small>Default display currency.</small></div><input value={settings.currency} onChange={e=>update('currency',e.target.value)}/></label><label><span>Localization</span><div><b>Language</b><small>Default storefront language.</small></div><input value={settings.language} onChange={e=>update('language',e.target.value)}/></label></div><div className="danger-zone"><div><h3>Reset demonstration catalog</h3><p>Remove locally persisted administrator changes and restore the original catalog.</p></div><button onClick={resetCatalog}><RotateCcw/>Reset catalog</button></div></div>}
